// Package skills carries the Agent Skills that `apic skill` prints and
// installs: the directories under skills/ in this repository, compiled
// into the binary so a project gets them from `apic init` or `apic skill
// install` without the repository or a network. The pack is apic (how to
// run, write and test requests with apic), api-design (how to design the
// API those requests call) and api-security (how to keep it safe and how
// to prove it with apic). Each SKILL.md is hand-written; apic's
// references/ is generated by `task skill` and a test in scripts/skilldocs
// keeps it current, and the same test checks every skill's front matter
// and the commands it names.
package skills

import (
	"embed"
	"io/fs"
	"sort"
)

//go:embed apic/SKILL.md apic/references api-design/SKILL.md api-design/references api-security/SKILL.md api-security/references
var files embed.FS

// Name is the primary skill's directory name, the one `apic skill` prints
// without an argument. Every skill is installed under its own name.
const Name = "apic"

// Names lists the skills in the pack, Name first and the rest sorted,
// each being a directory under skills/.
func Names() []string {
	entries, err := fs.ReadDir(files, ".")
	if err != nil {
		return []string{Name}
	}
	var rest []string
	for _, e := range entries {
		if e.IsDir() && e.Name() != Name {
			rest = append(rest, e.Name())
		}
	}
	sort.Strings(rest)
	return append([]string{Name}, rest...)
}

// Has reports whether name is a skill in the pack.
func Has(name string) bool {
	for _, n := range Names() {
		if n == name {
			return true
		}
	}
	return false
}

// Files returns the named skill's files by path relative to its
// directory (SKILL.md, references/…), or nil for a name not in the pack.
func Files(name string) map[string]string {
	if !Has(name) {
		return nil
	}
	out := map[string]string{}
	_ = fs.WalkDir(files, name, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		data, err := fs.ReadFile(files, path)
		if err != nil {
			return err
		}
		out[path[len(name)+1:]] = string(data)
		return nil
	})
	return out
}

// Paths lists the named skill's file paths, SKILL.md first and the rest
// sorted; empty for a name not in the pack.
func Paths(name string) []string {
	all := Files(name)
	if all == nil {
		return nil
	}
	var paths []string
	for p := range all {
		if p != "SKILL.md" {
			paths = append(paths, p)
		}
	}
	sort.Strings(paths)
	return append([]string{"SKILL.md"}, paths...)
}
